/**
 * Direction visuelle : Aquarelle de contrôle — dashboard asymétrique, chiffres respirables,
 * calendrier prioritaire et cartes translucides pour transformer la charge en décisions lisibles.
 */
import { motion } from "framer-motion";
import { ArrowUpRight, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, Clock3, Ellipsis, Filter, Flame, FolderKanban, Inbox, MoreHorizontal, Paperclip, Plus, Search, SlidersHorizontal, Sparkles, Star, Target, Users } from "lucide-react";
import { addDays, endOfDay, endOfWeek, format, isBefore, isSameDay, isWithinInterval, parseISO, startOfDay, startOfWeek } from "date-fns";
import { fr } from "date-fns/locale";
import { useEffect, useState } from "react";
import { PlannerShell } from "@/components/PlannerShell";
import { TaskModal } from "@/components/TaskModal";
import { usePlannerStore } from "@/store/usePlannerStore";
import { useSupabaseTaskSync } from "@/hooks/useSupabaseTaskSync";
import { useSupabaseTeamSync } from "@/hooks/useSupabaseTeamSync";
import { isSupabaseConfigured, supabase } from "@/lib/supabase";
import ErrorBoundary from "@/components/ErrorBoundary";
import { AgentMultiSelect } from "@/components/AgentMultiSelect";
import { InviteCollaboratorModal } from "@/components/InviteCollaboratorModal";
import { NewProjectModal } from "@/components/NewProjectModal";
import { CustomSelect } from "@/components/CustomControls";
import { isAdminRole } from "@/lib/team";
import type { PlannerProject, PlannerTask, TaskPriority } from "@/lib/types";
import ProfileView from "@/pages/ProfileView";
import CalendarWorkspace from "@/pages/CalendarWorkspace";
import ChatWorkspace from "@/pages/ChatWorkspace";
import SettingsWorkspace from "@/pages/SettingsWorkspace";
import { useSupabaseProjectSync } from "@/hooks/useSupabaseProjectSync";

const people = [{ id: "sam", initials: "SA", name: "Sam", color: "#69D2FF" }, { id: "michael", initials: "MI", name: "Michael", color: "#B5A1FF" }, { id: "bradley", initials: "BR", name: "Bradley", color: "#6FE3C1" }, { id: "daniel", initials: "DA", name: "Daniel", color: "#F0B36D" }, { id: "herve", initials: "HE", name: "Hervé", color: "#FF8BA7" }];
export default function Home() { const activeView = usePlannerStore((state) => state.activeView); return <PlannerShell><ErrorBoundary resetKey={activeView}><Workspace /></ErrorBoundary></PlannerShell>; }
function Workspace() { useSupabaseTaskSync(); useSupabaseTeamSync(); useSupabaseProjectSync(); const view = usePlannerStore((state) => state.activeView); const [settledView, setSettledView] = useState(view); const [isTransitioning, setIsTransitioning] = useState(false); const [transitionsEnabled, setTransitionsEnabled] = useState(() => localStorage.getItem("me-planner-motion") !== "off"); useEffect(() => { const refresh = () => setTransitionsEnabled(localStorage.getItem("me-planner-motion") !== "off"); window.addEventListener("me-planner-preferences", refresh); return () => window.removeEventListener("me-planner-preferences", refresh); }, []); useEffect(() => { if (view === settledView) return; if (!transitionsEnabled) { setSettledView(view); setIsTransitioning(false); return; } setIsTransitioning(true); const timer = window.setTimeout(() => { setSettledView(view); setIsTransitioning(false); }, 220); return () => window.clearTimeout(timer); }, [view, settledView, transitionsEnabled]); if (isTransitioning) return <WorkspaceSkeleton />; switch (settledView) { case "calendar": return <CalendarWorkspace key={settledView} />; case "tasks": return <TasksView key={settledView} />; case "projects": return <ProjectsView key={settledView} />; case "inbox": return <InboxView key={settledView} />; case "chat": return <ChatWorkspace key={settledView} />; case "admin": return <AdminView key={settledView} />; case "settings": return <SettingsWorkspace key={settledView} />; case "profile": return <ProfileView key={settledView} />; case "dashboard": default: return <DashboardView key="dashboard" />; } }

function WorkspaceSkeleton() { const view = usePlannerStore((state) => state.activeView); return <div className="workspace-skeleton" aria-busy="true" aria-live="polite"><div className="skeleton-view-header"><div className="skeleton-stack"><span className="skeleton-block skeleton-eyebrow" /><span className="skeleton-block skeleton-title" /><span className="skeleton-block skeleton-subtitle" /></div><div className="skeleton-actions"><span className="skeleton-block skeleton-button" /><span className="skeleton-block skeleton-button skeleton-button-primary" /></div></div>{view === "calendar" ? <><div className="skeleton-toolbar glass-panel"><span className="skeleton-block skeleton-period" /><span className="skeleton-block skeleton-tabs" /><span className="skeleton-block skeleton-icon" /></div><div className="skeleton-calendar glass-panel"><div className="skeleton-calendar-head">{Array.from({ length: 7 }, (_, index) => <span className="skeleton-block" key={index} />)}</div><div className="skeleton-calendar-body">{Array.from({ length: 28 }, (_, index) => <span className="skeleton-block" key={index} />)}</div></div></> : <div className="skeleton-content-grid">{Array.from({ length: view === "tasks" ? 7 : 6 }, (_, index) => <span className={`skeleton-block skeleton-card ${index === 0 ? "skeleton-card-wide" : ""}`} key={index} />)}</div>}</div>; }

function DashboardView() {
  const store = usePlannerStore(); const { tasks } = store; const active = tasks.filter((task) => task.status !== "done").length; const done = tasks.filter((task) => task.status === "done").length; const progress = tasks.length ? Math.round(tasks.reduce((sum, task) => sum + task.progress, 0) / tasks.length) : 0;
  return <PageFrame eyebrow="Mardi 11 août 2026" title={<>Bonjour Eldo, <em>on avance.</em></>} subtitle="Voici le tempo de votre équipe pour aujourd’hui." actions={<><button className="secondary-button compact" onClick={() => store.setView("calendar")}><CalendarDays size={16} /> Ouvrir le calendrier</button><button className="primary-button compact" onClick={() => store.openTaskModal()}><Plus size={16} /> Nouvelle tâche</button></>}><div className="eyebrow-row"><span className="status-pill"><i /> Espace synchronisé</span></div><div className="metrics-grid"><MetricCard label="Tâches actives" value={`${active}`} suffix="sur 12" icon={<Target size={17} />} accent="cyan" trend="+12%" detail="vs. semaine dernière" /><MetricCard label="En cours" value={`${progress}%`} suffix="du planning" icon={<Flame size={17} />} accent="mint" trend="+8%" detail="rythme collectif" /><MetricCard label="Terminées" value={`${done}`} suffix="aujourd’hui" icon={<Check size={17} />} accent="lavender" trend="+4" detail="depuis ce matin" /><MetricCard label="Temps focus" value="3h 42" suffix="restantes" icon={<Clock3 size={17} />} accent="peach" trend="64%" detail="capacité organisée" /></div><div className="dashboard-grid"><section className="glass-panel calendar-panel"><PanelHeader eyebrow="Votre rythme" title="Planning de la semaine" action={<button className="view-all-button" onClick={() => store.setView("calendar")}>Voir le calendrier <ArrowUpRight size={14} /></button>} /><MiniWeek /><div className="agenda-list">{tasks.slice(0, 4).map((task, index) => <AgendaRow key={task.id} task={task} index={index} onToggle={() => store.toggleTask(task.id)} onOpen={() => store.openTaskModal(task.id)} />)}</div><button className="add-slot" onClick={() => store.openTaskModal()}><Plus size={15} /> Ajouter une plage au planning</button></section><div className="dashboard-side"><section className="glass-panel workload-panel"><PanelHeader eyebrow="Capacité équipe" title="Charge de travail" action={<button className="icon-button subtle"><MoreHorizontal size={17} /></button>} /><div className="workload-total"><strong>74<span>%</span></strong><div><span className="trend-up">↗ 6,4%</span><small>vs. semaine précédente</small></div></div><div className="workload-bars">{people.slice(0, 4).map((person, index) => <div className="workload-row" key={person.id}><div className="person-meta"><div className="avatar" style={{ background: `${person.color}20`, color: person.color }}>{person.initials}</div><span>{person.name}</span></div><div className="bar-track"><i style={{ width: `${[84, 72, 58, 42][index]}%`, background: person.color }} /></div><strong>{[84, 72, 58, 42][index]}%</strong></div>)}</div><button className="text-button centered" onClick={() => store.setView("admin")}>Voir l’équipe complète <ArrowUpRight size={14} /></button></section><section className="glass-panel activity-panel"><PanelHeader eyebrow="Flux d’activité" title="Derniers mouvements" action={<button className="icon-button subtle"><Ellipsis size={17} /></button>} /><ActivityFeed /></section></div></div><div className="bottom-strip"><div className="strip-intro"><div className="strip-icon"><Sparkles size={17} /></div><div><span className="eyebrow">Prêt pour le prochain mouvement ?</span><strong>Votre journée a encore de la marge.</strong></div></div><div className="strip-stats"><div><span>Projets actifs</span><strong>04</strong></div><div><span>Échéances proches</span><strong>02</strong></div><div><span>Messages non lus</span><strong>07</strong></div></div><button className="icon-button strip-arrow" onClick={() => store.openTaskModal()}><ArrowUpRight size={18} /></button></div>{!isSupabaseConfigured && <div className="demo-notice">● Mode démo actif · connectez Supabase pour synchroniser l’espace d’équipe</div>}<TaskModal /></PageFrame>;
}

function CalendarView() { const store = usePlannerStore(); const [offset, setOffset] = useState(0); const weekStart = addDays(startOfWeek(new Date(2026, 7, 11), { weekStartsOn: 1 }), offset * 7); const days = Array.from({ length: 7 }, (_, index) => addDays(weekStart, index)); const hours = Array.from({ length: 10 }, (_, index) => index + 8); return <PageFrame eyebrow="Calendrier opérationnel" title={<>Votre planning, <em>en mouvement.</em></>} subtitle={`Semaine du ${format(weekStart, "d MMMM", { locale: fr })} au ${format(days[6], "d MMMM", { locale: fr })}.`} actions={<><button className="secondary-button compact" onClick={() => setOffset(0)}>Aujourd’hui</button><button className="primary-button compact" onClick={() => store.openTaskModal()}><Plus size={16} /> Nouvelle tâche</button></>}><div className="calendar-toolbar glass-panel"><div className="calendar-nav"><button className="icon-button" onClick={() => setOffset(offset - 1)}><ChevronLeft size={17} /></button><strong>{format(weekStart, "MMMM yyyy", { locale: fr })}</strong><button className="icon-button" onClick={() => setOffset(offset + 1)}><ChevronRight size={17} /></button></div><div className="view-switch"><button className="active">Semaine</button><button onClick={() => store.setView("tasks")}>Liste</button><button>Timeline</button><button>Gantt</button></div><div className="toolbar-actions"><button className="icon-button"><Filter size={16} /></button><button className="icon-button"><SlidersHorizontal size={16} /></button></div></div><div className="glass-panel calendar-shell"><div className="calendar-grid-head"><div className="time-column-label">CET</div>{days.map((day) => <div className={`day-label ${day.getDate() === 11 ? "today" : ""}`} key={day.toISOString()}><span>{format(day, "EEE", { locale: fr })}</span><strong>{format(day, "d")}</strong></div>)}</div><div className="calendar-grid-body"><div className="time-column">{hours.map((hour) => <span key={hour}>{hour}:00</span>)}</div>{days.map((day, dayIndex) => <div className="calendar-day-column" key={day.toISOString()}>{hours.map((hour) => <div className="hour-cell" key={hour} />)}{dayIndex < 5 && <CalendarEvent task={store.tasks[dayIndex]} top={`${8 + dayIndex * 14}%`} height={`${14 + (dayIndex % 2) * 7}%`} onClick={() => store.openTaskModal(store.tasks[dayIndex]?.id)} />}</div>)}</div></div><div className="calendar-legend"><span><i className="legend-dot cyan" />Northstar rebrand</span><span><i className="legend-dot lavender" />Équipe produit</span><span><i className="legend-dot mint" />Studio Aurora</span><span><i className="legend-dot peach" />Portail BTL</span></div></PageFrame>; }

function TasksView() {
  const store = usePlannerStore();
  const [dateFilter, setDateFilter] = useState<DateFilter>("all");
  const [priorityFilter, setPriorityFilter] = useState<TaskPriority | "all">("all");
  const [sortBy, setSortBy] = useState<SortOption>("date_asc");
  const canManageTeam = isAdminRole(store.profile.role);
  const allowedAgentIds = canManageTeam ? store.selectedAgentIds : [store.profile.id, "self"];
  const scopedTasks = store.tasks.filter((task) => allowedAgentIds.includes(task.assigneeId));
  const visible = scopedTasks.filter((task) => `${task.title} ${task.project}`.toLowerCase().includes(store.search.toLowerCase())).filter((task) => matchesDateFilter(task, dateFilter)).filter((task) => priorityFilter === "all" || task.priority === priorityFilter).sort((a, b) => compareTasks(a, b, sortBy));
  const activeFilters = Number(dateFilter !== "all") + Number(priorityFilter !== "all");
  const clearFilters = () => { setDateFilter("all"); setPriorityFilter("all"); setSortBy("date_asc"); };
  const selectedMembers = store.teamMembers.filter((member) => store.selectedAgentIds.includes(member.id));
  return <PageFrame eyebrow={canManageTeam ? "Pilotage d’équipe" : "Espace personnel"} title={canManageTeam ? <>Les tâches de <em>l’équipe.</em></> : <>Mes tâches <em>en clair.</em></>} subtitle={canManageTeam ? "Suivez l’avancement de plusieurs agents dans un même flux." : "Les actions qui méritent votre attention maintenant."} actions={<button className="primary-button compact" onClick={() => store.openTaskModal()}><Plus size={16} /> Nouvelle tâche</button>}>
    {canManageTeam && <div className="team-scope-toolbar glass-panel"><div><span className="eyebrow">Périmètre de pilotage</span><strong>{selectedMembers.length === store.teamMembers.length ? "Toute l’équipe" : `${selectedMembers.length} agent${selectedMembers.length > 1 ? "s" : ""} sélectionné${selectedMembers.length > 1 ? "s" : ""}`}</strong></div><AgentMultiSelect members={store.teamMembers} selectedIds={store.selectedAgentIds} onToggle={store.toggleAgent} onSelectAll={store.selectAllAgents} onClear={store.clearAgentSelection} /><div className="scope-stat"><span>Avancement moyen</span><strong>{averageProgress(scopedTasks)}%</strong></div><div className="scope-stat"><span>À risque</span><strong className="risk-value">{scopedTasks.filter((task) => task.status === "blocked" || task.priority === "urgent").length}</strong></div></div>}
    <div className="task-toolbar glass-panel"><div className="inline-search"><Search size={16} /><input value={store.search} onChange={(event) => store.setSearch(event.target.value)} placeholder={canManageTeam ? "Rechercher dans les tâches de l’équipe…" : "Rechercher dans mes tâches…"} /></div><div className="filter-actions"><div className="filter-control"><Filter size={14} /><span className="sr-only">Filtrer par date</span><CustomSelect value={dateFilter} onChange={(value) => setDateFilter(value as DateFilter)} options={[{ value: "all", label: "Toutes les dates" }, { value: "today", label: "Aujourd’hui" }, { value: "week", label: "Cette semaine" }, { value: "overdue", label: "En retard" }]} ariaLabel="Filtrer par date" /></div><div className="filter-control"><Target size={14} /><span className="sr-only">Filtrer par priorité</span><CustomSelect value={priorityFilter} onChange={(value) => setPriorityFilter(value as TaskPriority | "all")} options={[{ value: "all", label: "Toutes les priorités" }, { value: "urgent", label: "Urgente" }, { value: "high", label: "Haute" }, { value: "medium", label: "Moyenne" }, { value: "low", label: "Basse" }]} ariaLabel="Filtrer par priorité" /></div><div className="filter-control"><SlidersHorizontal size={14} /><span className="sr-only">Trier les tâches</span><CustomSelect value={sortBy} onChange={(value) => setSortBy(value as SortOption)} options={[{ value: "date_asc", label: "Date proche" }, { value: "date_desc", label: "Date lointaine" }, { value: "priority_desc", label: "Priorité forte" }, { value: "title_asc", label: "Titre A–Z" }]} ariaLabel="Trier les tâches" /></div>{activeFilters > 0 && <button className="clear-filters" onClick={clearFilters}>{activeFilters} filtre{activeFilters > 1 ? "s" : ""} · Effacer</button>}</div></div>
    <div className="task-list-panel glass-panel"><div className="task-list-head"><span>{visible.length} tâche{visible.length > 1 ? "s" : ""} visible{visible.length > 1 ? "s" : ""}</span><span>{canManageTeam ? `${selectedMembers.length} agent${selectedMembers.length > 1 ? "s" : ""}` : activeFilters > 0 ? "Filtre actif" : "Cette semaine"}</span></div>{visible.length > 0 ? visible.map((task) => <TaskListRow key={task.id} task={task} onOpen={() => store.openTaskModal(task.id)} onToggle={() => store.toggleTask(task.id)} onStar={() => store.toggleStar(task.id)} />) : <div className="task-empty"><Filter size={18} /><strong>Aucune tâche dans ce périmètre.</strong><span>Sélectionnez un autre agent ou élargissez vos filtres pour retrouver le fil.</span><button className="text-button" onClick={clearFilters}>Réinitialiser les filtres <ArrowUpRight size={14} /></button></div>}</div><TaskModal />
  </PageFrame>;
}

function ProjectsView() {
  const store = usePlannerStore();
  const canManageTeam = isAdminRole(store.profile.role);
  const allowedAgentIds = canManageTeam ? store.selectedAgentIds : [store.profile.id, "self"];
  const scopedTasks = store.tasks.filter((task) => allowedAgentIds.includes(task.assigneeId));
  const projects = summarizeProjects(scopedTasks, store.projects);
  return <PageFrame eyebrow={canManageTeam ? "Portefeuille piloté" : "Portefeuille"} title={<>Projets qui gardent <em>le cap.</em></>} subtitle={canManageTeam ? "Comparez l’avancement des projets selon les agents sélectionnés." : "Un aperçu des espaces actifs et de leur prochaine étape."} actions={canManageTeam ? <button className="primary-button compact" onClick={() => store.openProjectModal()}><Plus size={16} /> Nouveau projet</button> : <button className="secondary-button compact" disabled title="Réservé aux administrateurs et directeurs"><Plus size={16} /> Nouveau projet</button>}>
    {canManageTeam && <div className="team-scope-toolbar glass-panel"><div><span className="eyebrow">Périmètre de pilotage</span><strong>{store.selectedAgentIds.length === store.teamMembers.length ? "Toute l’équipe" : `${store.selectedAgentIds.length} agent${store.selectedAgentIds.length > 1 ? "s" : ""} sélectionné${store.selectedAgentIds.length > 1 ? "s" : ""}`}</strong></div><AgentMultiSelect members={store.teamMembers} selectedIds={store.selectedAgentIds} onToggle={store.toggleAgent} onSelectAll={store.selectAllAgents} onClear={store.clearAgentSelection} /><div className="scope-stat"><span>Tâches suivies</span><strong>{scopedTasks.length}</strong></div><div className="scope-stat"><span>Progression moyenne</span><strong>{averageProgress(scopedTasks)}%</strong></div></div>}
    {projects.length ? <div className="project-cards-grid">{projects.map((project) => <motion.div whileHover={{ y: -3 }} className="project-card glass-panel project-management-card" key={project.name}><div className="project-card-top"><i style={{ background: project.color }} /><span className={`project-risk ${project.risk ? "is-risk" : ""}`}>{project.risk ? `${project.risk} à risque` : "Dans le rythme"}</span><button className="icon-button subtle" aria-label={`Options du projet ${project.name}`}><MoreHorizontal size={16} /></button></div><h3>{project.name}</h3><p>{project.description}</p><div className="project-card-meta"><span>{project.done} / {project.total} tâches terminées</span><span>{project.progress}%</span></div><div className="project-progress"><i style={{ width: `${project.progress}%`, background: project.color }} /></div><div className="project-card-footer"><span>{project.ownerCount} agent{project.ownerCount > 1 ? "s" : ""} affecté{project.ownerCount > 1 ? "s" : ""}</span><strong>{project.open} ouvertes</strong></div></motion.div>)}</div> : <div className="management-empty glass-panel"><FolderKanban size={22} /><strong>Aucun projet dans ce périmètre.</strong><span>Sélectionnez plusieurs agents ou réinitialisez la sélection pour retrouver la vue portefeuille.</span></div>}
    <NewProjectModal />
  </PageFrame>;
}

function InboxView() { return <PageFrame eyebrow="Centre de notifications" title={<>Garder le fil, <em>sans bruit.</em></>} subtitle="Les informations importantes, regroupées au même endroit."><div className="inbox-panel glass-panel">{[{ dot: "cyan", title: "Sam vous a assigné une tâche", body: "Finaliser la proposition commerciale · Northstar rebrand", time: "Il y a 8 min" }, { dot: "mint", title: "Revue du parcours onboarding approche de l’échéance", body: "Échéance aujourd’hui à 12:00", time: "Il y a 34 min" }, { dot: "lavender", title: "Vous avez été mentionné dans une conversation", body: "Michael · Équipe produit", time: "Il y a 1 h" }, { dot: "peach", title: "Tâche terminée par Daniel", body: "Préparer les assets de lancement", time: "Il y a 2 h" }].map((item) => <div className="inbox-row" key={item.title}><div className={`notification-dot ${item.dot}`} /><div className="inbox-copy"><strong>{item.title}</strong><span>{item.body}</span></div><time>{item.time}</time><button className="icon-button subtle"><MoreHorizontal size={16} /></button></div>)}</div></PageFrame>; }

function ChatView() { return <PageFrame eyebrow="Communication interne" title={<>Les conversations qui <em>font avancer.</em></>} subtitle="Retrouvez les échanges globaux, privés et par projet."><div className="chat-layout"><div className="glass-panel conversation-list"><div className="conversation-head"><strong>Conversations</strong><button className="icon-button subtle"><Plus size={16} /></button></div>{["Global · équipe BTL", "Northstar rebrand", "Michael · produit", "Studio Aurora"].map((name, index) => <button className={`conversation-item ${index === 0 ? "active" : ""}`} key={name}><div className="avatar avatar-self">{["BT", "NS", "MI", "SA"][index]}</div><div><strong>{name}</strong><span>{["Sam : La revue est prête pour 15h.", "Vous : Je prends la prochaine passe.", "Michael : Je partage le parcours.", "Bradley a ajouté une réaction."][index]}</span></div><small>{["09:42", "Hier", "Lun.", "Ven."][index]}</small></button>)}</div><div className="glass-panel chat-window"><div className="chat-window-head"><div><strong>Global · équipe BTL</strong><span>12 membres · 4 en ligne</span></div><button className="icon-button"><MoreHorizontal size={17} /></button></div><div className="message-flow"><div className="date-separator"><span>Aujourd’hui</span></div><ChatMessage initials="SA" name="Sam" time="09:38" color="#69D2FF">La proposition commerciale est prête pour une dernière revue. J’ai laissé les points ouverts dans la checklist.</ChatMessage><ChatMessage initials="EL" name="Vous" time="09:42" color="#B5A1FF" own>Parfait. Je prends la prochaine passe avant le point client de 11h.</ChatMessage><ChatMessage initials="MI" name="Michael" time="09:46" color="#6FE3C1">Je viens d’ajouter le dernier écran du parcours onboarding. <strong>@Eldo</strong>, ton retour sur la hiérarchie m’aiderait.</ChatMessage></div><div className="chat-composer"><button className="icon-button"><Paperclip size={17} /></button><input placeholder="Écrire un message…" /><button className="primary-button compact"><ArrowUpRight size={16} /></button></div></div></div></PageFrame>; }

function AdminView() {
  const store = usePlannerStore();
  const canManageTeam = isAdminRole(store.profile.role);
  const [inviteOpen, setInviteOpen] = useState(false);
  if (!canManageTeam) return <PageFrame eyebrow="Accès restreint" title={<>La vue équipe est <em>réservée.</em></>} subtitle="Les indicateurs détaillés sont disponibles pour les administrateurs et directeurs."><div className="access-denied glass-panel"><Users size={24} /><strong>Vous n’avez pas accès au pilotage collectif.</strong><span>Votre espace personnel reste disponible depuis Calendrier et Mes tâches.</span><button className="secondary-button compact" onClick={() => store.setView("calendar")}><CalendarDays size={15} /> Ouvrir mon calendrier</button></div></PageFrame>;
  const scopedTasks = store.tasks.filter((task) => store.selectedAgentIds.includes(task.assigneeId));
  const riskyTasks = scopedTasks.filter((task) => task.status === "blocked" || task.priority === "urgent");
  const activeAgents = store.teamMembers.filter((member) => member.status !== "offline").length;
  return <PageFrame eyebrow="Pilotage d’équipe" title={<>La vue collective, <em>sans angle mort.</em></>} subtitle="Comparez l’évolution des tâches, la charge et les risques de chaque agent.">
    <div className="team-scope-toolbar glass-panel"><div><span className="eyebrow">Périmètre de pilotage</span><strong>{store.selectedAgentIds.length === store.teamMembers.length ? "Toute l’équipe" : `${store.selectedAgentIds.length} agent${store.selectedAgentIds.length > 1 ? "s" : ""} sélectionné${store.selectedAgentIds.length > 1 ? "s" : ""}`}</strong></div><AgentMultiSelect members={store.teamMembers} selectedIds={store.selectedAgentIds} onToggle={store.toggleAgent} onSelectAll={store.selectAllAgents} onClear={store.clearAgentSelection} /><div className="scope-stat"><span>Agents actifs</span><strong>{activeAgents}</strong></div><div className="scope-stat"><span>Avancement moyen</span><strong>{averageProgress(scopedTasks)}%</strong></div><div className="scope-stat"><span>À risque</span><strong className="risk-value">{riskyTasks.length}</strong></div></div>
    <div className="agent-management-grid">{store.teamMembers.filter((member) => store.selectedAgentIds.includes(member.id)).map((member) => { const memberTasks = scopedTasks.filter((task) => task.assigneeId === member.id); const progress = averageProgress(memberTasks); const risk = memberTasks.filter((task) => task.status === "blocked" || task.priority === "urgent").length; return <motion.article whileHover={{ y: -3 }} className="agent-management-card glass-panel" key={member.id}><div className="agent-management-head"><div className="agent-option-avatar" style={{ color: member.color, background: `${member.color}20` }}>{member.initials}</div><div><strong>{member.name}</strong><span>{member.role === "super_admin" ? "Super Admin" : member.role === "director" ? "Directeur" : "Équipe"}</span></div><i className={`agent-status-dot ${member.status}`} /></div><div className="agent-progress-meta"><span>Progression moyenne</span><strong>{progress}%</strong></div><div className="agent-progress-track"><i style={{ width: `${progress}%`, background: member.color }} /></div><div className="agent-management-footer"><span>{memberTasks.length} tâche{memberTasks.length > 1 ? "s" : ""}</span><span className={risk ? "risk-value" : "healthy-value"}>{risk ? `${risk} à risque` : "Rythme sain"}</span></div></motion.article>; })}</div>
    <div className="management-two-column"><div className="glass-panel admin-table"><PanelHeader eyebrow="Équipe Mon Essentiel" title="Collaborateurs" action={<button className="primary-button compact" onClick={() => setInviteOpen(true)}><Plus size={15} /> Inviter</button>} /><div className="table-head"><span>Collaborateur</span><span>Rôle</span><span>Charge</span><span>Statut</span></div>{store.teamMembers.filter((member) => store.selectedAgentIds.includes(member.id)).map((member) => { const memberTasks = scopedTasks.filter((task) => task.assigneeId === member.id); return <div className="table-row" key={member.id}><div className="person-meta"><div className="avatar" style={{ background: `${member.color}20`, color: member.color }}>{member.initials}</div><strong>{member.name}</strong></div><span>{member.role === "super_admin" ? "Super Admin" : member.role === "director" ? "Directeur" : member.role === "admin" ? "Administrateur" : "Équipe"}</span><div className="mini-progress"><i style={{ width: `${averageProgress(memberTasks)}%`, background: member.color }} /></div><span className={`online-status ${member.status}`}><i /> {member.status === "online" ? "En ligne" : member.status === "away" ? "Absent" : "Hors ligne"}</span></div>; })}</div><div className="glass-panel management-risk-panel"><PanelHeader eyebrow="À surveiller" title="Tâches à risque" action={<span className="risk-value">{riskyTasks.length}</span>} />{riskyTasks.length ? riskyTasks.slice(0, 6).map((task) => { const owner = store.teamMembers.find((member) => member.id === task.assigneeId); return <button className="risk-task-row" key={task.id} onClick={() => store.openTaskModal(task.id)}><span className="risk-task-dot" style={{ background: task.projectColor }} /><span><strong>{task.title}</strong><small>{owner?.name ?? "Agent"} · {task.project}</small></span><span className="task-status status-blocked">{task.status === "blocked" ? "Bloquée" : "Urgente"}</span></button>; }) : <div className="management-empty small"><CheckCircle2 size={18} /><strong>Aucun risque identifié.</strong><span>Le périmètre sélectionné suit son rythme.</span></div>}</div></div><AccountManagementPanel />{inviteOpen && <InviteCollaboratorModal onClose={() => setInviteOpen(false)} />}
  </PageFrame>;
}

const accountRoleOptions = [{ value: "member", label: "Membre" }, { value: "director", label: "Directeur" }, { value: "admin", label: "Administrateur" }, { value: "super_admin", label: "Super Admin" }];

function AccountManagementPanel() {
  const store = usePlannerStore();
  const canManageAccounts = store.profile.role === "super_admin" || store.profile.role === "admin";
  const [busyId, setBusyId] = useState<string | null>(null);
  const [feedback, setFeedback] = useState("");
  if (!canManageAccounts) return <section className="glass-panel account-management-panel account-management-locked"><div className="settings-icon"><Users size={17} /></div><div><span className="eyebrow">Gestion des comptes</span><strong>Réservée aux administrateurs et superadministrateurs.</strong><p>Les directeurs peuvent piloter l’équipe, mais la modification des rôles est protégée.</p></div></section>;
  const updateRole = async (memberId: string, nextRole: string) => {
    if (memberId === store.profile.id && nextRole === "member") { setFeedback("Vous ne pouvez pas retirer votre propre accès administrateur depuis cette vue."); return; }
    setBusyId(memberId); setFeedback("");
    try {
      if (supabase) {
        const { error } = await supabase.from("profiles").update({ role: nextRole }).eq("id", memberId);
        if (error) throw error;
      }
      store.setTeamMembers(store.teamMembers.map((member) => member.id === memberId ? { ...member, role: nextRole } : member));
      if (memberId === store.profile.id) store.setProfile({ role: nextRole });
      setFeedback("Rôle mis à jour.");
    } catch (error) { setFeedback(error instanceof Error ? error.message : "Impossible de modifier ce rôle."); }
    finally { setBusyId(null); }
  };
  return <section className="glass-panel account-management-panel"><PanelHeader eyebrow="Administration" title="Gestion des comptes" action={<span className="scope-stat">{store.teamMembers.length} comptes</span>} /><p className="account-management-intro">Attribuez le niveau d’accès adapté à chaque collaborateur. Les changements sont appliqués dans Supabase lorsque la session est connectée.</p><div className="account-list">{store.teamMembers.map((member) => <div className="account-row" key={member.id}><div className="person-meta"><div className="avatar" style={{ background: `${member.color}20`, color: member.color }}>{member.initials}</div><div><strong>{member.name}</strong><small>{member.id === store.profile.id ? "Compte actif" : "Profil d’équipe"}</small></div></div><CustomSelect value={member.role} onChange={(value) => void updateRole(member.id, value)} options={accountRoleOptions} disabled={busyId === member.id} ariaLabel={`Rôle de ${member.name}`} /><span className={`account-status ${busyId === member.id ? "is-saving" : ""}`}>{busyId === member.id ? "Enregistrement…" : "Actif"}</span></div>)}</div>{feedback && <div className="account-feedback" role="status">{feedback}</div>}</section>;
}

function SettingsView() { return <PageFrame eyebrow="Préférences" title={<>Configurer votre <em>cadence.</em></>} subtitle="Adaptez l’espace de travail à votre manière de penser."><div className="settings-grid"><div className="glass-panel settings-card"><div className="settings-card-head"><div className="settings-icon"><CalendarDays size={18} /></div><div><h3>Apparence</h3><p>Thème et densité visuelle de l’application.</p></div></div><SettingLine label="Thème actif" value="Dark" /><SettingLine label="Animations" toggle /></div><div className="glass-panel settings-card"><div className="settings-card-head"><div className="settings-icon mint"><Clock3 size={18} /></div><div><h3>Organisation</h3><p>Vos préférences de planning et de notifications.</p></div></div><SettingLine label="Premier jour de la semaine" value="Lundi" /><SettingLine label="Langue" value="Français" /><SettingLine label="Son d’interface" toggle /></div></div></PageFrame>; }

function PageFrame({ eyebrow, title, subtitle, actions, children }: { eyebrow: string; title: React.ReactNode; subtitle: string; actions?: React.ReactNode; children: React.ReactNode }) { return <div className="workspace-content"><div className="view-header"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p className="hero-subtitle">{subtitle}</p></div>{actions && <div className="hero-actions">{actions}</div>}</div>{children}</div>; }
function MetricCard({ label, value, suffix, icon, accent, trend, detail }: { label: string; value: string; suffix: string; icon: React.ReactNode; accent: string; trend: string; detail: string }) { return <motion.div whileHover={{ y: -3 }} className={`metric-card glass-panel accent-${accent}`}><div className="metric-head"><span>{label}</span><div className="metric-icon">{icon}</div></div><div className="metric-value"><strong>{value}</strong><span>{suffix}</span></div><div className="metric-foot"><span className="trend">↗ {trend}</span><small>{detail}</small></div></motion.div>; }
function PanelHeader({ eyebrow, title, action }: { eyebrow: string; title: string; action?: React.ReactNode }) { return <div className="panel-header"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div>{action}</div>; }
function MiniWeek() { const days = Array.from({ length: 7 }, (_, index) => addDays(startOfWeek(new Date(2026, 7, 11), { weekStartsOn: 1 }), index)); return <div className="mini-week">{days.map((day) => <button className={day.getDate() === 11 ? "selected" : ""} key={day.toISOString()}><span>{format(day, "EEE", { locale: fr }).replace(".", "")}</span><strong>{format(day, "d")}</strong>{day.getDate() === 11 && <i />}</button>)}</div>; }
function AgendaRow({ task, index, onToggle, onOpen }: { task: PlannerTask; index: number; onToggle: () => void; onOpen: () => void }) { const person = people.find((item) => item.id === task.assigneeId) ?? people[0]; return <motion.div layout className="agenda-row" onClick={onOpen}><div className="agenda-time"><strong>{task.start}</strong><span>{task.end}</span></div><div className="agenda-line"><i style={{ background: task.projectColor }} /><div className="agenda-card"><div className="agenda-card-top"><span className="agenda-category">{task.category}</span><button className="icon-button subtle" onClick={(event) => { event.stopPropagation(); onToggle(); }} aria-label="Marquer la tâche"><Check size={15} /></button></div><strong>{task.title}</strong><div className="agenda-meta"><span><i style={{ background: person.color }} />{person.name}</span><span>{task.estimate}</span><span className={`priority priority-${task.priority}`}>{priorityName(task.priority)}</span></div></div></div></motion.div>; }
function ActivityFeed() { return <div className="activity-feed">{[{ initials: "DA", color: "#F0B36D", text: <><strong>Daniel</strong> a terminé <b>Préparer les assets</b></>, time: "il y a 12 min" }, { initials: "MI", color: "#B5A1FF", text: <><strong>Michael</strong> a commenté <b>Parcours onboarding</b></>, time: "il y a 34 min" }, { initials: "SA", color: "#69D2FF", text: <><strong>Sam</strong> vous a assigné <b>Proposition commerciale</b></>, time: "il y a 1 h" }].map((item) => <div className="activity-item" key={item.initials + item.time}><div className="avatar" style={{ background: `${item.color}20`, color: item.color }}>{item.initials}</div><div><p>{item.text}</p><span>{item.time}</span></div></div>)}</div>; }
function CalendarEvent({ task, top, height, onClick }: { task: PlannerTask; top: string; height: string; onClick: () => void }) { return <button className="calendar-event" onClick={onClick} style={{ top, height, background: `${task.projectColor}18`, borderColor: `${task.projectColor}66`, color: task.projectColor }}><strong>{task.title}</strong><span>{task.start} · {task.end}</span></button>; }
function TaskListRow({ task, onOpen, onToggle, onStar }: { task: PlannerTask; onOpen: () => void; onToggle: () => void; onStar: () => void }) { const livePerson = usePlannerStore((state) => state.teamMembers.find((member) => member.id === task.assigneeId)); const person = livePerson ?? people.find((item) => item.id === task.assigneeId) ?? people[0]; return <motion.div layout className="task-list-row"><button className={`task-checkbox ${task.status === "done" ? "done" : ""}`} onClick={onToggle}>{task.status === "done" && <Check size={13} />}</button><button className="task-row-main" onClick={onOpen}><span className="task-row-title">{task.title}</span><span className="task-row-project"><i style={{ background: task.projectColor }} />{task.project}</span></button><span className={`task-status status-${task.status}`}>{task.status === "done" ? "Terminée" : task.status === "in_progress" ? "En cours" : task.status === "blocked" ? "Bloquée" : "À faire"}</span><span className="task-assignee"><span className="avatar tiny" style={{ background: `${person.color}20`, color: person.color }}>{person.initials}</span>{person.name}</span><button className={`star-button ${task.starred ? "starred" : ""}`} onClick={onStar}><Star size={16} fill={task.starred ? "currentColor" : "none"} /></button><button className="icon-button subtle"><MoreHorizontal size={16} /></button></motion.div>; }
function ChatMessage({ initials, name, time, color, own, children }: { initials: string; name: string; time: string; color: string; own?: boolean; children: React.ReactNode }) { return <div className={`chat-message ${own ? "own" : ""}`}><div className="avatar" style={{ background: `${color}20`, color }}>{initials}</div><div><div className="message-meta"><strong>{name}</strong><span>{time}</span></div><p>{children}</p></div></div>; }
function SettingLine({ label, value, toggle }: { label: string; value?: string; toggle?: boolean }) { return <div className="settings-line"><span>{label}</span>{toggle ? <button className="toggle active"><i /></button> : <strong>{value} <ChevronRight size={15} /></strong>}</div>; }
function priorityName(priority: TaskPriority) { return priority === "urgent" ? "Urgente" : priority === "high" ? "Haute" : priority === "medium" ? "Planifiée" : "Basse"; }
type DateFilter = "all" | "today" | "week" | "overdue";
type SortOption = "date_asc" | "date_desc" | "priority_desc" | "title_asc";
function taskDate(task: PlannerTask) { return task.date ? parseISO(task.date) : startOfDay(new Date(2026, 7, 11)); }
function matchesDateFilter(task: PlannerTask, filter: DateFilter) { const date = taskDate(task); const today = startOfDay(new Date()); if (filter === "all") return true; if (filter === "today") return isSameDay(date, today); if (filter === "overdue") return isBefore(date, today) && task.status !== "done"; return isWithinInterval(date, { start: startOfWeek(today, { weekStartsOn: 1 }), end: endOfWeek(today, { weekStartsOn: 1 }) }); }
function compareTasks(a: PlannerTask, b: PlannerTask, sort: SortOption) { if (sort === "title_asc") return a.title.localeCompare(b.title, "fr"); if (sort === "priority_desc") return priorityWeight(b.priority) - priorityWeight(a.priority); const direction = sort === "date_desc" ? -1 : 1; return (taskDate(a).getTime() - taskDate(b).getTime()) * direction || a.start.localeCompare(b.start); }
function priorityWeight(priority: TaskPriority) { return { urgent: 4, high: 3, medium: 2, low: 1 }[priority]; }
function averageProgress(tasks: PlannerTask[]) { return tasks.length ? Math.round(tasks.reduce((sum, task) => sum + task.progress, 0) / tasks.length) : 0; }
type ProjectSummary = { name: string; color: string; description: string; progress: number; total: number; done: number; open: number; risk: number; ownerCount: number };
function summarizeProjects(tasks: PlannerTask[], definitions: PlannerProject[]): ProjectSummary[] { const names = Array.from(new Set([...definitions.map((project) => project.name), ...tasks.map((task) => task.project)])); return names.map((name) => { const definition = definitions.find((project) => project.name === name); const projectTasks = tasks.filter((task) => task.project === name); const ownerCount = definition?.memberIds.length || new Set(projectTasks.map((task) => task.assigneeId)).size; return { name, color: definition?.color ?? projectTasks[0]?.projectColor ?? "#69D2FF", description: definition?.description ?? "Projet suivi par l’équipe.", progress: averageProgress(projectTasks), total: projectTasks.length, done: projectTasks.filter((task) => task.status === "done").length, open: projectTasks.filter((task) => task.status !== "done").length, risk: projectTasks.filter((task) => task.status === "blocked" || task.priority === "urgent").length, ownerCount }; }); }
